// Güvenlik paneli: PIR hareket görünce siren çalar; web sayfasından kurulur ve çözülür.
#include <WiFi.h>
#include <WebServer.h>
#include <time.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const int PIR_PIN = 27;
const int BUZZER_PIN = 25;
const int LED_PIN = 26;
const unsigned long ISINMA_MS = 30000;        // PIR açılışta 30 sn ısınır; bu sürede hareket sayılmaz
const unsigned long ALARM_SURESI_MS = 20000;  // siren en çok bu kadar çalar, sonra panel kurulu bekler
const unsigned long SIREN_ADIM_MS = 250;      // siren ve LED bu aralıkla açılıp kapanır
const int SIREN_FREKANS = 2500;               // Hz
const long SAAT_DILIMI = 3 * 3600;            // Türkiye: UTC+3
const int OLAY_SAYISI = 10;                   // sayfada son 10 alarm

WebServer sunucu(80);
bool kurulu = false;
bool alarmCaliyor = false;
bool sirenAcik = false;
unsigned long alarmBaslangic = 0;
int oncekiPir = LOW;
// Halka tampon: yeni olay en eskinin yerine yazılır.
String olaylar[OLAY_SAYISI];
int olaySirasi = 0;
int olayAdedi = 0;

const char SAYFA[] PROGMEM = R"HTML(<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Güvenlik paneli</title>
<style>
body{font-family:sans-serif;max-width:420px;margin:auto;padding:16px;text-align:center}
#durum{font-size:22px;font-weight:bold;padding:16px;border-radius:12px;background:#e5e7eb}
#durum.kurulu{background:#fef3c7}
#durum.alarm{background:#dc2626;color:#fff}
button{font-size:20px;margin:12px 6px;padding:12px 28px;border-radius:10px;border:none;color:#fff}
ul{text-align:left;padding-left:20px}
li{margin:4px 0;font-family:monospace}
</style></head><body>
<h1>Güvenlik paneli</h1>
<div id="durum">Bağlanıyor...</div>
<button style="background:#b45309" onclick="komut('/kur')">Kur</button>
<button style="background:#15803d" onclick="komut('/coz')">Çöz</button>
<h2>Son 10 alarm</h2>
<ul id="liste"></ul>
<script>
var ciz = function (d) {
  var k = document.getElementById('durum');
  if (d.alarm) { k.textContent = 'ALARM! Hareket algılandı'; k.className = 'alarm'; }
  else if (d.kurulu && d.isinma > 0) { k.textContent = 'Kurulu (sensör ısınıyor: ' + d.isinma + ' sn)'; k.className = 'kurulu'; }
  else if (d.kurulu) { k.textContent = 'Kurulu: bekçide'; k.className = 'kurulu'; }
  else { k.textContent = 'Çözük: alarm kapalı'; k.className = ''; }
  var l = document.getElementById('liste');
  l.innerHTML = '';
  if (!d.olaylar.length) l.innerHTML = '<li>Henüz alarm yok.</li>';
  d.olaylar.forEach(function (o) { var li = document.createElement('li'); li.textContent = o; l.appendChild(li); });
};
var yenile = function () {
  fetch('/durum').then(function (r) { return r.json(); }).then(ciz)
    .catch(function () { document.getElementById('durum').textContent = 'ESP32 cevap vermedi.'; });
};
var komut = function (yol) { fetch(yol).then(function (r) { return r.json(); }).then(ciz); };
yenile();
setInterval(yenile, 2000);
</script></body></html>)HTML";

// NTP saati varsa "GG.AA SS:DD:ss", yoksa açılıştan beri geçen süre "+SS:DD:ss".
String zamanMetni() {
  struct tm t;
  char m[24];
  if (getLocalTime(&t, 10)) {
    snprintf(m, sizeof m, "%02d.%02d %02d:%02d:%02d", t.tm_mday, t.tm_mon + 1, t.tm_hour, t.tm_min, t.tm_sec);
  } else {
    unsigned long sn = millis() / 1000;
    snprintf(m, sizeof m, "+%02lu:%02lu:%02lu", sn / 3600, (sn / 60) % 60, sn % 60);
  }
  return String(m);
}

void olayEkle(const String& metin) {
  olaylar[olaySirasi] = metin;
  olaySirasi = (olaySirasi + 1) % OLAY_SAYISI;
  if (olayAdedi < OLAY_SAYISI) olayAdedi++;
}

void sirenYaz(bool acik) {
  if (acik == sirenAcik) return;
  sirenAcik = acik;
  digitalWrite(LED_PIN, acik ? HIGH : LOW);
  if (acik) tone(BUZZER_PIN, SIREN_FREKANS);
  else noTone(BUZZER_PIN);
}

void alarmBaslat() {
  alarmCaliyor = true;
  alarmBaslangic = millis();
  String zaman = zamanMetni();
  olayEkle(zaman + "  Hareket algılandı");
  Serial.print("ALARM: hareket var! ");
  Serial.println(zaman);
}

void alarmDurdur() {
  alarmCaliyor = false;
  sirenYaz(false);
}

String durumJson() {
  String j = "{\"kurulu\":";
  j += kurulu ? "true" : "false";
  j += ",\"alarm\":";
  j += alarmCaliyor ? "true" : "false";
  j += ",\"isinma\":";
  unsigned long simdi = millis();
  j += simdi < ISINMA_MS ? (ISINMA_MS - simdi) / 1000 + 1 : 0UL;
  j += ",\"olaylar\":[";
  for (int i = 0; i < olayAdedi; i++) {
    int k = (olaySirasi - 1 - i + OLAY_SAYISI) % OLAY_SAYISI;  // en yeni önce
    if (i > 0) j += ",";
    j += "\"";
    j += olaylar[k];
    j += "\"";
  }
  j += "]}";
  return j;
}

void anaSayfa() {
  sunucu.send(200, "text/html", SAYFA);
}

void kur() {
  kurulu = true;
  Serial.println("Panel kuruldu.");
  sunucu.send(200, "application/json", durumJson());
}

void coz() {
  kurulu = false;
  alarmDurdur();
  Serial.println("Panel cozuldu.");
  sunucu.send(200, "application/json", durumJson());
}

void durum() {
  sunucu.send(200, "application/json", durumJson());
}

void setup() {
  Serial.begin(115200);
  pinMode(PIR_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUZZER_PIN, OUTPUT);

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Baglandi. Tarayicida ac: http://");
  Serial.println(WiFi.localIP());
  configTime(SAAT_DILIMI, 0, "pool.ntp.org");

  sunucu.on("/", anaSayfa);
  sunucu.on("/kur", kur);
  sunucu.on("/coz", coz);
  sunucu.on("/durum", durum);
  sunucu.begin();
  Serial.println("PIR isiniyor (30 sn). Panel cozuk.");
}

void loop() {
  sunucu.handleClient();

  // Isınma bitince PIR'i oku. Yalnız LOW -> HIGH geçişi yeni olaydır; aynı hareket bir kez yazılır.
  if (millis() > ISINMA_MS) {
    int pir = digitalRead(PIR_PIN);
    if (kurulu && !alarmCaliyor && pir == HIGH && oncekiPir == LOW) alarmBaslat();
    oncekiPir = pir;
  }

  if (alarmCaliyor) {
    unsigned long gecen = millis() - alarmBaslangic;
    if (gecen > ALARM_SURESI_MS) {
      alarmDurdur();
      Serial.println("Alarm suresi doldu. Panel kurulu bekliyor.");
    } else {
      sirenYaz((gecen / SIREN_ADIM_MS) % 2 == 0);
    }
  } else if (kurulu) {
    // Kuruluyken LED 2 sn'de bir kısa yanar.
    digitalWrite(LED_PIN, millis() % 2000 < 100 ? HIGH : LOW);
  } else {
    digitalWrite(LED_PIN, LOW);
  }
  delay(10);
}
